const body = $input.first().json;
const secret = $env.N8N_WEBHOOK_SECRET || '';
const header = $input.first().headers && ($input.first().headers['x-webhook-secret'] || $input.first().headers['X-Webhook-Secret']);
if (secret && header !== secret) { throw new Error('Invalid webhook secret'); }
return [{ json: {
  phone: body.phone,
  guestName: body.guestName,
  bookingCode: body.bookingCode,
  checkIn: body.checkIn,
  mapUrl: body.mapUrl,
  messageId: body.messageId,
  templateKey: 'checkin-reminder',
  templateName: 'checkin_reminder',
  language: 'en'
}}];
